.sl-contact-minimal { background-color: var(--smartlearn-bg); color: var(--smartlearn-text); font-family: var(--smartlearn-body-font, system-ui, sans-serif); padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 3vw, 2rem); }
.sl-contact-minimal .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; }
.sl-contact-minimal .sl-header { max-width: 720px; margin-inline: auto; text-align: center; margin-bottom: clamp(2.5rem, 5vw, 3.5rem); }
.sl-contact-minimal .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-weight: 800; font-size: clamp(1.85rem, 3.5vw, 2.5rem); color: var(--smartlearn-text); margin: 0 0 0.75rem; }
.sl-contact-minimal .sl-subtitle { color: var(--smartlearn-text-muted); font-size: 1.1rem; line-height: 1.6; margin: 0; }
.sl-contact-minimal .sl-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.5rem; }
.sl-contact-minimal .minimal-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 1rem); padding: clamp(1.5rem, 3vw, 2rem); text-align: center; transition: transform 0.25s ease, box-shadow 0.25s ease; }
.sl-contact-minimal .minimal-card-featured { border-color: var(--smartlearn-primary); }
.sl-contact-minimal .minimal-card:hover { transform: translateY(-4px); box-shadow: 0 15px 30px rgba(0, 0, 0, 0.08); }
.sl-contact-minimal .icon-circle { width: 76px; height: 76px; border-radius: 50%; margin: 0 auto 1.5rem; display: flex; align-items: center; justify-content: center; background-color: rgba(148, 163, 184, 0.12); background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent); color: var(--smartlearn-primary); }
.sl-contact-minimal .icon-circle-featured { background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); }
.sl-contact-minimal .sl-card-title { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.25rem; font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.75rem; }
.sl-contact-minimal .sl-card-desc { color: var(--smartlearn-text-muted); font-size: 0.975rem; line-height: 1.6; margin: 0 0 1.25rem; }
.sl-contact-minimal .sl-card-link { color: var(--smartlearn-primary); font-weight: 700; text-decoration: none; }
.sl-contact-minimal .sl-card-link-phone { color: var(--smartlearn-text); font-size: 1.15rem; }
.sl-contact-minimal .sl-card-link:hover { text-decoration: underline; }
.sl-contact-minimal .sl-card-link:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-contact-minimal .sl-card-address { color: var(--smartlearn-text); font-weight: 600; margin: 0; line-height: 1.5; }
@media (max-width: 767px) { .sl-contact-minimal .sl-grid { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { .sl-contact-minimal .minimal-card { transition: none; } .sl-contact-minimal .minimal-card:hover { transform: none; } }
